from __future__ import annotations

from typing import List, Optional

from fastapi import FastAPI, HTTPException

from .models import LoanApplication, Status

app = FastAPI(
    title='Loan Applications API',
    version='1.0.0',
)

# [SLIDE 11] In-memory "database" — holds loans while the app is running.
loans: list = []

# Assigns the next loan_id. The generated LoanApplication model has no id field,
# so we track it here and attach it to each stored loan.
_next_id: int = 1


@app.get('/loans', response_model=List[LoanApplication])
def list_loans(status: Optional[Status] = None) -> List[LoanApplication]:
    """
    List all loan applications. If a status is provided, return only the
    matching ones.
    """
    if status is not None:
        return [loan for loan in loans if loan.status == status.value]
    return loans


@app.post('/loans', response_model=LoanApplication, status_code=201)
def create_loan(body: LoanApplication) -> LoanApplication:
    """
    Create a new loan application — add the incoming application to the list
    and return it.
    """
    global _next_id
    body.loan_id = _next_id
    _next_id += 1
    loans.append(body)
    return body


@app.get('/loans/{loan_id}', response_model=LoanApplication)
def get_loan(loan_id: int) -> LoanApplication:
    """
    Get one loan application by ID, or raise a 404 if it's not there.
    """
    for loan in loans:
        if loan.loan_id == loan_id:
            return loan
    raise HTTPException(status_code=404, detail="Loan not found")
